                # from a storage fault by the caller via BlockingIOError,
                # which is an OSError subclass -- let it propagate.
                raise
        else:  # pragma: no cover - non-POSIX platforms
            locked = False
        yield fd
    finally:
        if fcntl is not None and locked:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError:
                pass
        try:
            os.close(fd)
        except OSError:
            pass

