def _take_over(
    self, operation, descriptor: dict
) -> ArtifactMirror:
    """Re-open an intact, never-committed mirror for a retried attempt.

    Only a ``bound`` mirror (provider never called) or a fully
    ``rolled_back`` mirror (every minted handle verified deleted and the
    old write set restored) can be restarted, and only with zero residual
    evidence and no durable event. The descriptor is reset to a fresh
    ``bound`` image so the executor re-describes kind/write set and mints
    NEW handles; stale handle pairs must not survive into the post-commit
    ownership check.
    """
    phase = descriptor.get("phase")
    if phase not in (PHASE_BOUND, PHASE_ROLLED_BACK):
        raise ArtifactStrandUnavailable(
            "mirror phase %r cannot be taken over" % phase
        )
    if phase == PHASE_BOUND and descriptor.get("handles"):
        raise ArtifactStrandUnavailable(
            "bound mirror already records handles"
        )
    if not self._clean_strand_descriptor(operation, descriptor):
        raise ArtifactStrandUnavailable(
            "surviving evidence blocks the mirror takeover"
        )
    # Reset the durable image to a fresh bound strand. Discard first so a
    # stale journal/snapshot/handle reference can never ride along.
    if not self.discard(operation.operation_id):
        raise ArtifactStrandUnavailable("stale mirror could not be removed")
    try:
        return self.create(operation)
    except OSError as exc:
        raise ArtifactStrandUnavailable(str(exc), 500)

